import pandas as pd
import os
import re

# Define the file paths
base_path = "/tmp/data/task_tbjc5eh2/dataset/TA/tables/english_table/Amadeus_Sales_and_Catering_Training"
files = {
    "Delphi & Delphi Core": os.path.join(base_path, "Delphi & Delphi Core.csv"),
    "Delphi Select": os.path.join(base_path, "Delphi Select.csv"),
    "MeetingBroker": os.path.join(base_path, "MeetingBroker.csv"),
    "Delphi Direct & Instant Booking": os.path.join(base_path, "Delphi Direct & Instant Booking.csv"),
    "Delphi Diagramming": os.path.join(base_path, "Delphi Diagramming.csv")
}

def count_sessions(df, session_type):
    """Count the number of session rows for a given session type"""
    count = 0
    found_section = False

    for idx, row in df.iterrows():
        # Convert row to string for checking
        row_str = str(row.values)

        # Check if we've found the session type section
        if session_type in row_str:
            found_section = True
            continue

        # If we've found the section, count non-empty rows until we hit another session type
        if found_section:
            # Check if we've hit another session type (stop counting)
            if "User Sessions" in row_str and session_type != "User Sessions":
                break
            if "Administrator Sessions" in row_str and session_type != "Administrator Sessions":
                break

            # Count rows that have actual session content (not just headers or empty rows)
            # Look for rows with time values like "1 HR", "30 MIN", etc.
            if any(str(cell) in ["1 HR", "2 HR", "30 MIN", "45 MIN", "2HR", "1 HR", "30MIN"] for cell in row.values):
                count += 1

    return count

# Read and analyze each file
results = {}

for product, filepath in files.items():
    try:
        # Read the CSV file
        df = pd.read_csv(filepath, header=None)

        # Find User Sessions count
        user_count = 0
        admin_count = 0

        # Look for the section markers
        for idx, row in df.iterrows():
            row_str = str(row.values)

            if "User Sessions" in row_str and "Administrator" not in row_str:
                # Found User Sessions section
                # Count subsequent rows with time values
                for j in range(idx + 1, len(df)):
                    next_row = df.iloc[j]
                    next_row_str = str(next_row.values)
                    # Stop if we hit another section
                    if "Administrator Sessions" in next_row_str:
                        break
                    # Check if this row has a time value indicating a session
                    if any(str(cell) in ["1 HR", "2 HR", "30 MIN", "45 MIN", "2HR", "1 HR", "30MIN", "15 MIN", "60 MIN"] 
                           for cell in next_row.values):
                        user_count += 1

            if "Administrator Sessions" in row_str:
                # Found Administrator Sessions section
                # Count subsequent rows with time values
                for j in range(idx + 1, len(df)):
                    next_row = df.iloc[j]
                    next_row_str = str(next_row.values)
                    # Stop if we hit another section
                    if "User Sessions" in next_row_str:
                        break
                    # Check if this row has a time value indicating a session
                    if any(str(cell) in ["1 HR", "2 HR", "30 MIN", "45 MIN", "2HR", "1 HR", "30MIN", "15 MIN", "60 MIN"] 
                           for cell in next_row.values):
                        admin_count += 1

        results[product] = {
            "user_sessions": user_count,
            "admin_sessions": admin_count,
            "total": user_count + admin_count
        }

    except Exception as e:
        print(f"Error processing {product}: {e}")
        results[product] = {"error": str(e)}

print(results)
