                # Count subsequent rows with time values
                for j in range(idx + 1, len(df)):
                    next_row = df.iloc[j]
                    next_row_str = str(next_row.values)
                    # Stop if we hit another section
                    if "User Sessions" in next_row_str:
                        break
                    # Check if this row has a time value indicating a session
                    if any(str(cell) in ["1 HR", "2 HR", "30 MIN", "45 MIN", "2HR", "1 HR", "30MIN", "15 MIN", "60 MIN"] 
                           for cell in next_row.values):
                        admin_count += 1

